def min_rests(n, activities):
    dp = [[0, 0], [0, 0]]
    for activity in activities:
        new_dp = [[float('inf'), float('inf')], [float('inf'), float('inf')]]
        if activity != 0:
            new_dp[activity % 2][0] = min(dp[(activity - 1) % 2]) + 1
        if activity == 0 or activity == 1:
            new_dp[0][1] = min(dp[1])
        if activity == 0 or activity == 2:
            new_dp[1][0] = min(dp[0])
        dp = new_dp
    return min(dp[0]) + min(dp[1])

