    dp = [[float('inf')] * 4 for _ in range(2)]
    dp[0][0] = dp[1][0] = 0

    for i in range(1, n + 1):
        current = (i - 1) % 2
        prev = current ^ 1

        for j in range(4):
            if j == 0:
                dp[current][j] = min(dp[prev][k] for k in [1, 2]) + 1
            elif j == 1:
                dp[current][j] = min(dp[prev][0], dp[prev][3])
            elif j == 2:
                dp[current][j] = min(dp[prev][0], dp[prev][1])
            else:
                dp[current][j] = dp[prev][j-1]

    return min(dp[(n-1)%2])

