def min_rest_days(n, activities):
    dp = [[float('inf')] * 4 for _ in range(4)]

    # Base case initialization
    dp[0][0] = 0  # No activity on the first day

    for i in range(n):
        for j in range(4):
            for k in range(4):
                if (j != k and (activities[i] == 3 or activities[i] == 0)):
                    dp[(j + 1) % 4][k] = min(dp[(j + 1) % 4][k], dp[j][k] + 1)
                elif (j != k and (activities[i] == 2 or activities[i] == 1)):
                    dp[(j + 2) % 4][k] = min(dp[(j + 2) % 4][k], dp[j][k] + 1)

    return min(dp[i][j] for i in range(4) for j in range(4))

